WITH sales_by_customer AS ( SELECT ss.ss_customer_sk, cd.cd_gender, cd.cd_purchase_estimate, hd.hd_vehicle_count, ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, ss.ss_sold_date_sk, ss.ss_net_paid, SUM(ss.ss_net_paid) OVER (PARTITION BY ss.ss_customer_sk ORDER BY ss.ss_sold_date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_paid, AVG(ss.ss_net_paid) OVER (PARTITION BY ss.ss_customer_sk ORDER BY ss.ss_sold_date_sk ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7d FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk ) SELECT ss_customer_sk, cd_gender, ib_income_band_sk, ib_lower_bound, ib_upper_bound, hd_vehicle_count, ss_sold_date_sk, cumulative_net_paid, moving_avg_7d, CASE WHEN cd_purchase_estimate < 1000 THEN 'Low' WHEN cd_purchase_estimate BETWEEN 1000 AND 5000 THEN 'Medium' WHEN cd_purchase_estimate > 5000 THEN 'High' ELSE 'Unknown' END AS purchase_estimate_category, DENSE_RANK() OVER (PARTITION BY cd_gender, ib_income_band_sk ORDER BY cumulative_net_paid DESC) AS gender_income_rank FROM sales_by_customer WHERE ss_sold_date_sk = (SELECT MAX(ss_sold_date_sk) FROM store_sales) ORDER BY cd_gender, ib_income_band_sk, gender_income_rank LIMIT 10
